using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Object=UnityEngine.Object;
public static class VerifyGameplayLightVisibility {
 static string Path(Transform t){string s=t.name;while(t.parent){t=t.parent;s=t.name+"/"+s;}return s;}
 static string[] Lighting(){var scene=SceneManager.GetActiveScene();return Object.FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(l=>l.gameObject.scene==scene).Select(l=>Path(l.transform)+"\t"+l.type+"\t"+l.lightmapBakeType+"\t"+l.enabled+"\t"+l.shadows).OrderBy(s=>s).ToArray();}
 public static string Before(){if(Application.isPlaying)throw new Exception("Edit mode required");File.WriteAllLines("output/Lighting/authored-before.tsv",Lighting());return "Recorded authored light states before Play Mode";}
 public static string Runtime(){if(!Application.isPlaying)throw new Exception("Play mode required");var scene=SceneManager.GetActiveScene();var controller=Object.FindObjectsByType<SceneLightVisibilityController>(FindObjectsSortMode.None).Single(c=>c.gameObject.scene==scene);var source=controller.ViewCamera;if(!source)throw new Exception("Player camera binding missing");var directionals=Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Where(l=>l.type==LightType.Directional&&l.gameObject.scene==scene).ToArray();var enabled=directionals.Select(l=>l.enabled).ToArray();var shadows=directionals.Select(l=>l.shadows).ToArray();var report=new List<string>();controller.EvaluateNow();report.Add("Player camera: "+Path(source.transform)+"; managed="+controller.ManagedLightCount+"; on="+controller.EnabledLightCount+"; shadowed="+controller.ShadowedLightCount);
  var go=new GameObject("Temporary light direction probe");var probe=go.AddComponent<Camera>();probe.cullingMask=0;probe.fieldOfView=source.fieldOfView;probe.aspect=source.aspect;probe.transform.position=source.transform.position;
  try{controller.ViewCamera=probe;for(int angle=0;angle<360;angle+=45){probe.transform.rotation=Quaternion.Euler(0,angle,0);controller.EvaluateNow();report.Add("View yaw "+angle+": enabled="+controller.EnabledLightCount+"; shadowed="+controller.ShadowedLightCount);}}
  finally{controller.ViewCamera=source;Object.DestroyImmediate(go);}
  bool same=true;for(int i=0;i<directionals.Length;i++)if(directionals[i].enabled!=enabled[i]||directionals[i].shadows!=shadows[i])same=false;report.Add((same?"PASS ":"FAIL ")+"Gameplay directional lights unchanged across all headings");report.Add((controller.ViewCamera==source?"PASS ":"FAIL ")+"Player camera binding restored after probe");string result=string.Join("\n",report);File.WriteAllText("output/Lighting/gameplay-validation.txt",result);return result;}
 public static string After(){if(Application.isPlaying)throw new Exception("Edit mode required");var before=File.ReadAllLines("output/Lighting/authored-before.tsv");var after=Lighting();bool same=before.SequenceEqual(after);File.WriteAllLines("output/Lighting/authored-after.tsv",after);string result=(same?"PASS ":"FAIL ")+"All "+after.Length+" Gameplay lights retain their authored enabled/shadow settings after returning to Edit Mode";File.AppendAllText("output/Lighting/gameplay-validation.txt","\n"+result);return result;}
}
